#include "simulation.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}
int main(int argc,char**argv){try{need(argc>1,"pass original data");Resources r(argv[1]);auto cfg=load_vehicle(r,3);auto body=load_geometry(r,cfg.body);auto driver=std::make_shared<const NativeDriver>(load_native_driver(r));auto seat=load_driver_placement(r,3,body);Geometry floor;floor.materials.push_back({"tarmac"});Mesh m;for(Vec p:{Vec{-100,0,-100},Vec{100,0,-100},Vec{100,0,100},Vec{-100,0,100}}){Vertex v;v.position=p;m.vertices.push_back(v);}m.indices={0,2,1,0,3,2};floor.meshes.push_back(m);Simulation sim(floor,cfg,translate({0,4,0}),{},driver,seat);Input input;input.eject=true;sim.step(input);auto state=sim.state();need(state.driver_ejected&&state.driver_bones,"native driver ejection publishes skeleton");auto first=state.driver_bones;auto old=point((*first)[0],{});need(length(old-point(state.car,{}))<4,"native seat launches near chassis");for(int i=0;i<250;i++)sim.step({});state=sim.state();need(state.driver_bones&&length(point((*state.driver_bones)[0],{})-old)>1,"native ragdoll moves");for(auto&bone:*state.driver_bones)for(float f:bone)need(std::isfinite(f),"finite native driver bones");need(state.collision_events&&!state.collision_events->empty(),"physics publishes collision audio events even between frames");uint64_t last=0;for(auto&e:*state.collision_events){need(e.id>last&&e.impulse>0&&e.closing_speed>.5f&&e.sound_category>=1&&e.sound_category<=11,"bounded native collision event data");last=e.id;}need(state.collision_events->size()<=128,"collision history bounded");sim.recover();need(!sim.state().driver_ejected&&!sim.state().driver_bones,"recovery removes ragdoll");need(length(point((*first)[0],{})-old)<1e-6f,"replay skeleton immutable");std::cout<<"native seat -> skinned ragdoll -> collision audio events -> recovery integration passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
